import{c as e,Q as r,j as a,m as o}from"./chunks/framework.BqPkuuVc.js";const s="/assets/audit.C9khfJgD.png",n="/assets/audit-entry-changes.CpoNDHCQ.png",i="/assets/machine-name-prompt.Jirlid3n.png",d="/assets/edit-competitor-audit.P4iLVcFs.png",f=JSON.parse('{"title":"Audit trail","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/audit-trail.md","filePath":"user/reference/audit-trail.md"}'),h={name:"user/reference/audit-trail.md"};function l(c,t,g,u,m,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="audit-trail" tabindex="-1">Audit trail <a class="header-anchor" href="#audit-trail" aria-label="Permalink to &quot;Audit trail&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and timing operators who need to know what changed in an event, when, and where it was changed from.</p><p>Every event keeps a record of every change made to it. This page explains what the record holds, how to read the <strong>Audit trail</strong> screen, and how to answer the questions people actually ask on the day.</p><h2 id="what-the-audit-trail-records" tabindex="-1">What the audit trail records <a class="header-anchor" href="#what-the-audit-trail-records" aria-label="Permalink to &quot;What the audit trail records&quot;">​</a></h2><p>The audit trail is a running list of every change to the event&#39;s data, in the order the changes happened. Each entry records:</p><ul><li><strong>when</strong> the change was made;</li><li><strong>what</strong> changed: which competitor, class, course, control, team or card download, and whether it was added, updated or removed;</li><li>the <strong>before and after</strong> values of every field that changed;</li><li>the <strong>source</strong>: whether an operator typed it, the entry desk did, an import brought it in, a card download or radio punch caused it, or Manager worked it out itself;</li><li>the <strong>computer</strong> it was made at, when a person made it.</li></ul><p>It covers imports, manual edits, card downloads, radio punches, assignments, overrides, deletions and changes to the event&#39;s own details. Every deletion is recorded, whatever route it took, so something that disappeared can always be traced.</p><p><strong>The audit trail is always on.</strong> There is no setting to turn it off, and it belongs to the event: it lives in the event&#39;s folder, travels with every <a href="./backup-and-restore">backup</a>, and comes back when the event is restored.</p><h2 id="the-audit-trail-screen" tabindex="-1">The Audit trail screen <a class="header-anchor" href="#the-audit-trail-screen" aria-label="Permalink to &quot;The Audit trail screen&quot;">​</a></h2><p>Open the event and choose <strong>Audit trail</strong> under <strong>Event data</strong> in the side menu.</p><p><img src="'+s+'" alt="The Audit trail screen, listing changes with their time, type, action, change, source and computer"></p><p>The newest changes are at the top. Each row shows:</p><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Time</strong></td><td>When the change was made.</td></tr><tr><td><strong>Type</strong></td><td>What kind of thing changed: Competitor, Class, Control, CardDownload…</td></tr><tr><td><strong>Action</strong></td><td><strong>Added</strong>, <strong>Updated</strong> or <strong>Removed</strong>, or the name of an import (<strong>Import entries</strong>, <strong>Import courses</strong>…).</td></tr><tr><td><strong>Change</strong></td><td>A one-line summary, such as &quot;Updated Competitor 106 · Class removed&quot;.</td></tr><tr><td><strong>Source</strong></td><td>Where the change came from (see <a href="#sources">Sources</a>).</td></tr><tr><td><strong>Computer</strong></td><td>Which computer it was made at (see <a href="#computers">Computers</a>).</td></tr></tbody></table><p>Two more columns, <strong>Category</strong> and <strong>Entity ID</strong>, are hidden to begin with. The column button at the right of the header row shows or hides columns and changes their order. Your choice is remembered on this computer.</p><p>Click a row to see exactly what changed. <strong>Changes</strong> lists each field with its value <strong>Before</strong> and <strong>After</strong>:</p><p><img src="'+n+'" alt="An expanded audit row showing a Changes table: ClassId from 1 to 2 and Si from 441003 to 8088671"></p><p>The field names here are Manager&#39;s own, so they&#39;re sometimes terser than the labels on screen. For example, <code>Si</code> is the card number, and <code>ClassId</code> is the class&#39;s number rather than its name.</p><p>To keep the list readable:</p><ul><li><strong>An import is one row.</strong> All the competitors, classes or courses an import added are folded under its row, which shows how many changes it made. Open the row to see them.</li><li><strong>A run of meshO Prime radio traffic is one row</strong>, such as &quot;meshO Prime stream · 47 lines&quot;. Prime&#39;s regular heartbeat messages are left out.</li><li><strong>Older entries load in pages.</strong> When there are more, a <strong>Load … more</strong> button appears at the bottom.</li></ul><p>The list doesn&#39;t update by itself. Click <strong>Refresh</strong> to see changes made since you opened it.</p><h3 id="finding-a-change" tabindex="-1">Finding a change <a class="header-anchor" href="#finding-a-change" aria-label="Permalink to &quot;Finding a change&quot;">​</a></h3><p>Use the boxes along the top to narrow the list. They combine, so you can ask for, say, everything the entry desk did in the last hour.</p><table tabindex="0"><thead><tr><th>Box</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Search</strong></td><td>Finds entries containing a word or number anywhere in their values: a name, a card number, a bib. It searches values, not field names, so searching &quot;Tim&quot; finds Tim rather than every entry with a time in it.</td></tr><tr><td><strong>Time</strong></td><td>Only the last 1, 5, 10, 15, 30 or 45 minutes, or the last 1 or 2 hours. Useful mid-event: &quot;what changed in the last ten minutes?&quot;</td></tr><tr><td><strong>Category</strong></td><td><strong>Entity</strong> (a competitor, class, course, and so on), <strong>Event</strong> (the event&#39;s own details), <strong>Import</strong>, or <strong>meshO Prime</strong>.</td></tr><tr><td><strong>Type</strong></td><td>One kind of thing: only Competitor changes, only CardDownload changes, and so on.</td></tr><tr><td><strong>Source</strong></td><td>One source, such as only <strong>Entry desk</strong> or only <strong>AI assistant</strong>.</td></tr><tr><td><strong>Computer</strong></td><td>One computer.</td></tr></tbody></table><p>Each box offers only the choices that actually appear in this event&#39;s trail. A source or computer that appears for the first time while the screen is open is offered after you click <strong>Refresh</strong>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>The <strong>Source</strong> column says where a change came from:</p><table tabindex="0"><thead><tr><th>Source</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Manual</strong></td><td>Made by an operator at the manager screens.</td></tr><tr><td><strong>Entry desk</strong></td><td>Made at the registration desk (<code>/rego</code>).</td></tr><tr><td><strong>Import</strong></td><td>Brought in by an import: entries, start lists, classes, courses, rankings, IOF IDs, Eventor, or <strong>Import from Backup</strong> on Card downloads.</td></tr><tr><td><strong>Ingest</strong></td><td>Arrived from the timing equipment: a card download, a radio punch, a meshO Prime message.</td></tr><tr><td><strong>Derived</strong></td><td>Worked out by Manager as a consequence of something else, such as a result recalculated after a card download or a team&#39;s total updated after a leg changed.</td></tr><tr><td><strong>Automatic</strong></td><td>Made by Manager because time passed: a competitor marked as started at their start time, or a result settled when the course closed.</td></tr><tr><td><strong>AI assistant</strong></td><td>Made by an <a href="./ai-assistants-mcp">AI assistant</a>. Hover over the source to see which of the assistant&#39;s tools made the change.</td></tr><tr><td><strong>Changes report</strong></td><td>Applied from another event&#39;s <a href="./../after-the-event/changes-report">changes report</a>.</td></tr><tr><td><strong>Bib allocation</strong></td><td>Written by a bib allocation.</td></tr><tr><td><strong>IOF ranking</strong></td><td>Written from the IOF world ranking.</td></tr><tr><td><strong>Start time move</strong></td><td>Part of moving every start in the event at once. One click moves hundreds of starts; this source shows they were one decision, not hundreds of separate edits.</td></tr></tbody></table><p><strong>Manual</strong>, <strong>Entry desk</strong>, <strong>AI assistant</strong> and the last four are all ordinary edits. The source only says how the edit was made. <strong>Derived</strong> and <strong>Automatic</strong> are things Manager did on its own: they follow from the other entries rather than being decisions anyone made.</p><h2 id="computers" tabindex="-1">Computers <a class="header-anchor" href="#computers" aria-label="Permalink to &quot;Computers&quot;">​</a></h2><p>An event is often run from several computers at once: the operator&#39;s console, a download laptop, one or two at the entry desk. The <strong>Computer</strong> column says which one each change was made at.</p><ul><li><strong>A named computer</strong> shows its name, such as &quot;Download station A&quot;.</li><li><strong>A computer nobody named</strong> shows its network address, such as <code>192.168.1.77</code>. It&#39;s still listed separately from every other computer.</li><li><strong>This server</strong> means the browser on the computer running meshO Manager itself.</li><li>A blank means <strong>no computer</strong> made the change: a radio punch, an automatic change, or an entry recorded before computers were tracked. In the <strong>Computer</strong> filter, these are listed as <strong>No computer</strong>.</li></ul><h3 id="naming-a-computer" tabindex="-1">Naming a computer <a class="header-anchor" href="#naming-a-computer" aria-label="Permalink to &quot;Naming a computer&quot;">​</a></h3><p>The first time Manager is opened in a browser, it asks you to <strong>Name this computer</strong>:</p><p><img src="'+i+'" alt="The &quot;Name this computer&quot; dialog, asking for a computer name such as &quot;Download lane A&quot; or &quot;Admin machine&quot;"></p><p>Give each one a name people will recognise later, such as &quot;Download lane A&quot; or &quot;Entry desk 2&quot;. Click <strong>Not now</strong> to skip it; the computer is listed by its address until it has a name. Rename it at any time in <strong>Settings → This computer</strong>, or from <strong>Settings → Printing</strong>, which uses the same name.</p><p>Things to know about names:</p><ul><li><strong>The name belongs to the browser, not the machine.</strong> It&#39;s stored in that browser. A second browser on the same laptop, or a browser whose site data has been cleared, counts as a separate, unnamed computer.</li><li><strong>Renaming doesn&#39;t rewrite history.</strong> Changes made under the old name keep it, so a renamed computer appears under both names in the <strong>Computer</strong> filter.</li><li><strong>A computer isn&#39;t a person.</strong> Manager doesn&#39;t know who was at the keyboard. A laptop three volunteers take turns on is one computer. Write a roster down if you need to know who was on which desk when.</li><li><strong>The browser on the server itself</strong> isn&#39;t asked for a name when it&#39;s opened at the server&#39;s own address (<code>localhost</code>). Its changes are shown as <strong>This server</strong>.</li></ul><h2 id="one-competitor-s-history" tabindex="-1">One competitor&#39;s history <a class="header-anchor" href="#one-competitor-s-history" aria-label="Permalink to &quot;One competitor&#39;s history&quot;">​</a></h2><p>To see the history of one competitor, open them (<strong>Edit competitor</strong>) and go to the <strong>Audit trail</strong> tab. It lists only that competitor&#39;s changes, in plain words rather than field names.</p><p><img src="'+d+'" alt="The Audit trail tab of Edit competitor for Alex Johnson: imported, card number set at the entry desk, start time set, marked on course, a radio punch, the card downloaded and the result set to OK"></p><p>Other examples of what it says:</p><ul><li>&quot;Card number set to 8088671&quot;</li><li>&quot;Class changed to M21E&quot;</li><li>&quot;Card 8776805 downloaded&quot;</li><li>&quot;Radio punch at control 31 (10:42:17)&quot;</li><li>&quot;Result set to MP&quot;</li><li>&quot;Manual punch override changed&quot;</li></ul><p>Click an entry for the before and after values. This is the quickest way to answer &quot;why does this runner have this result?&quot; or &quot;who changed their class?&quot;.</p><h2 id="questions-the-audit-trail-answers" tabindex="-1">Questions the audit trail answers <a class="header-anchor" href="#questions-the-audit-trail-answers" aria-label="Permalink to &quot;Questions the audit trail answers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>How to answer it</th></tr></thead><tbody><tr><td>What did the entry desk change today?</td><td><strong>Source: Entry desk</strong>.</td></tr><tr><td>What&#39;s changed in the last ten minutes?</td><td><strong>Time: Last 10 min</strong>.</td></tr><tr><td>Why is this competitor in a different class?</td><td>Open the competitor and look at their <strong>Audit trail</strong> tab.</td></tr><tr><td>A card download has disappeared. Where did it go?</td><td><strong>Type: CardDownload</strong>, and search for the card number. A deleted download is recorded as <strong>Removed</strong>. Its file is still on disk, so <a href="./../running-the-event/card-download#import-from-backup">Import from Backup</a> can bring it back.</td></tr><tr><td>What did the AI assistant do?</td><td><strong>Source: AI assistant</strong>.</td></tr><tr><td>Which of today&#39;s changes should go to tomorrow&#39;s event?</td><td>The <a href="./../after-the-event/changes-report">changes report</a> reads the trail and lists the net changes to people.</td></tr><tr><td>What came in with that entries import?</td><td>Find the <strong>Import entries</strong> row and open it.</td></tr><tr><td>What was done on the download laptop?</td><td><strong>Computer:</strong> the laptop&#39;s name, or its address if it has none.</td></tr></tbody></table><h2 id="what-the-audit-trail-doesn-t-record" tabindex="-1">What the audit trail doesn&#39;t record <a class="header-anchor" href="#what-the-audit-trail-doesn-t-record" aria-label="Permalink to &quot;What the audit trail doesn&#39;t record&quot;">​</a></h2><ul><li><strong>Who</strong> made a change. Manager records the computer, not the person.</li><li><strong>Settings that aren&#39;t part of one event</strong>: Settings, printers and computers, the hire-card list, the club and competitor registries, and a multi-stage event&#39;s own setup.</li><li><strong>The bytes of an uploaded map.</strong> The change to the event&#39;s map settings is recorded, but not the image itself.</li><li><strong>Exports and printing.</strong> Exporting results or printing a splits slip changes nothing in the event, so nothing is recorded.</li><li><strong>Rejected input.</strong> A duplicate radio punch or a repeated card read that Manager ignored never became a change, so it isn&#39;t listed.</li><li><strong>Changes made while an event is being replayed.</strong></li><li><strong>Changes made outside Manager</strong>, such as files edited by hand in the event folder.</li><li><strong>The event itself once deleted.</strong> The trail lives inside the event&#39;s folder and goes with it. <a href="./backup-and-restore">Back up</a> first if you might need the history later.</li></ul><p>A <strong>duplicated</strong> event starts with a fresh, empty trail. It&#39;s a new event, so it doesn&#39;t inherit the history of the one it was copied from. A <strong>restored</strong> event keeps its trail, because it&#39;s the same event brought back.</p><h2 id="if-the-trail-can-t-be-written-or-read" tabindex="-1">If the trail can&#39;t be written or read <a class="header-anchor" href="#if-the-trail-can-t-be-written-or-read" aria-label="Permalink to &quot;If the trail can&#39;t be written or read&quot;">​</a></h2><p>Recording a change never gets in the way of the change itself. If the trail can&#39;t be written, for example because the disk is refusing writes, the event carries on, and Manager raises an <strong>alert</strong>: &quot;Changes to this event have stopped being recorded in its audit trail.&quot; The alert is withdrawn once recording resumes. If the whole event folder stops taking changes, Manager shows <strong>This event can&#39;t be saved</strong> instead. See <a href="./backup-and-restore#when-an-event-can-t-be-saved">When an event can&#39;t be saved</a>.</p><p>If the trail can&#39;t be <strong>read</strong>, the Audit trail screen says so instead of showing an empty list: &quot;The audit trail could not be read, so nothing can be shown here. This does not mean no changes were made.&quot; An empty list only ever means that nothing matches.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./backup-and-restore">Backup and restore</a> — the trail travels with every backup</li><li><a href="./../running-the-event/card-download">Card download</a> — Import from Backup brings back a removed download</li><li><a href="./ai-assistants-mcp">AI assistants (MCP)</a> — what an assistant can change, and how its changes are marked</li><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a> — the Edit competitor dialog</li><li><a href="./multi-operator-setup">Multi-operator setup</a> — running an event from several computers</li></ul>',53)])])}const b=e(h,[["render",l]]);export{f as __pageData,b as default};
